// ============================================================================
// src/lib/tools/stp-election-calculator/golden-vectors.ts
// ----------------------------------------------------------------------------
// GOLDEN VECTORS for the spanning tree election calculator.
//
// Every expected root, role, root path cost, root port and port cost below was
// derived on 2026-11-08 by a separate Python oracle (work/oracle.py in the
// build's work folder), not by running this engine. The oracle reads its cost
// tables from the saved source texts (MikroTik's port-cost-mode table,
// Extreme's "configure stpd ports cost" defaults, the Cisco, Aruba and Arista
// records, the Cisco Press table) and elects by a different method: every
// bridge starts by claiming to be the root, every port sends its designated
// priority vector to the other ports of its segment, every bridge keeps the
// best vector it hears (never its own ports'), the rounds repeat until nothing
// changes, and each port's role then comes from comparing what it would send
// with what it hears. The engine instead runs a shortest-path pass and three
// sorts. work/gen_vectors.py wrote the two generated tables from the oracle's
// output (the Example of deck slide 259, the four sample chips, fourteen
// hand-shaped variations and sixty seeded random topologies; and the cost rows),
// so no expected value was typed by hand. The refusals, the speed spellings
// and the sentences are written out after them, each with the rule it pins.
// GOLDEN_VECTOR_SET_ID changes whenever a vector changes (the api-sync rule).
// ============================================================================

import { run, runApi, SPEEDS, type StpRequest, type StpResult, type ElectionResult, type CostResult } from "./compute"; // the engine's API entries and its table
import { EXAMPLE_ELECTION_REQUEST, EXAMPLE_COST_REQUEST, SAMPLES } from "./examples"; // the page's Examples and chips, pinned below

/** The set id: dated, changed with any vector (scripts/check-api-sync.mjs compares it with scripts/api-sync.json). */
export const GOLDEN_VECTOR_SET_ID = "stp-election-calculator-golden-2026-11-08b"; // 08b: Huawei read in a browser (2.5 Gb/s row, 802.1t default), Cisco's command reference

/** One vector: a request (or raw API text), and the fields expected or the error expected. */
export interface StpVector {
  /** A stable id. */
  id: string;
  /** Where the expected values come from. */
  note: string;
  /** The request object (run()). */
  request?: StpRequest;
  /** Or the raw API body (runApi()). */
  api?: string;
  /** Election fields expected (from the oracle). */
  election?: { root: number; roles: string[]; rootPathCosts: number[]; rootPorts: (string | null)[]; costs: number[] };
  /** Cost fields expected (from the oracle's source-read tables). */
  cost?: { id: string; mbps: number; long: number; longSources: string[]; short: number | null; shortSources: string[] | null };
  /** Text the reading's sentences must contain. */
  contains?: { verdictText?: string; warnings?: string[]; notes?: string[]; steps?: string[] };
  /** Text no warning may contain (a warning that must not fire). */
  noWarning?: string;
  /** The error expected, as a pattern over its message. */
  expectError?: RegExp;
}

/** The page's Examples and chips, re-exported by the conventional names. */
export { EXAMPLE_ELECTION_REQUEST, EXAMPLE_COST_REQUEST, SAMPLES }; // shared with the component through examples.ts

/** Elections from the oracle: [id, note, method, topology, expected]. */
type ElectionRow = [string, string, "long" | "short", string, NonNullable<StpVector["election"]>]; // one generated row
