/** Every vector, in order. */
export const STP_VECTORS: readonly StpVector[] = Object.freeze([...ELECTION_VECTORS, ...COST_VECTORS, ...OTHER_VECTORS]); // tables first, then the rest

/** The report verifyVectors returns. */
export interface VerifyReport {
  /** The set id. */
  setId: string;
  /** Vectors run. */
  total: number;
  /** Vectors that passed. */
  passed: number;
  /** One line per failure (empty when all pass). */
  failures: string[];
}

/**
 * Run every vector, and check that the page's Examples and chips are computed vectors.
 * @returns the report (failures empty when all pass)
 */
export function verifyVectors(): VerifyReport {
  const failures: string[] = []; // collected
  const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // exact, as JSON
  for (const v of STP_VECTORS) { // each vector
    let r: StpResult | null = null; // the reading
    try {
      r = v.api !== undefined ? runApi(v.api) : run(v.request as StpRequest); // the API text or the request
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e); // the refusal
      if (!v.expectError) failures.push(`${v.id}: unexpected error: ${msg}`); // should have computed
      else if (!v.expectError.test(msg)) failures.push(`${v.id}: error mismatch: ${msg}`); // the wrong refusal
      continue; // next vector
    } // ran
    if (v.expectError) { failures.push(`${v.id}: expected an error, got a reading`); continue; } // should have refused
    if (v.election) { // an election from the oracle
      const e = r as ElectionResult; // the reading
      const got = { root: e.root, roles: e.ports.map((p) => p.role), rootPathCosts: e.bridges.map((b) => b.rootPathCost), rootPorts: e.bridges.map((b) => (b.rootPort === null ? null : `${e.ports[b.rootPort].bridgeName}:${e.ports[b.rootPort].number}`)), costs: e.ports.map((p) => p.cost) }; // the same fields
      if (!same(got, v.election)) failures.push(`${v.id}: election differs: ${JSON.stringify(got)}`); // a role or a cost moved
    } // election
    if (v.cost) { // a cost row from the oracle
      const c = r as CostResult; // the reading
      const got = { id: c.speed.id, mbps: c.speed.mbps, long: c.speed.long?.value, longSources: [...(c.speed.long?.sources ?? [])].sort(), short: c.speed.short ? c.speed.short.value : null, shortSources: c.speed.short ? [...c.speed.short.sources].sort() : null }; // the same fields
      if (!same(got, v.cost)) failures.push(`${v.id}: cost differs: ${JSON.stringify(got)}`); // a value or a source moved
    } // cost
    const k = v.contains ?? {}; // the texts expected
    const rec = r as unknown as { verdictText?: string; warnings?: string[]; notes?: string[]; rootStep?: { text: string }; rootPortSteps?: { text: string }[]; designatedSteps?: { text: string }[]; blockedSteps?: { text: string }[] }; // the sentence fields
    const steps = [rec.rootStep?.text ?? "", ...(rec.rootPortSteps ?? []).map((s) => s.text), ...(rec.designatedSteps ?? []).map((s) => s.text), ...(rec.blockedSteps ?? []).map((s) => s.text)]; // every step
    if (k.verdictText && !String(rec.verdictText ?? "").includes(k.verdictText)) failures.push(`${v.id}: verdict lacks "${k.verdictText}"`); // the verdict
    for (const s of k.warnings ?? []) if (!(rec.warnings ?? []).some((w) => w.includes(s))) failures.push(`${v.id}: no warning contains "${s}"`); // warnings
    for (const s of k.notes ?? []) if (!(rec.notes ?? []).some((n) => n.includes(s))) failures.push(`${v.id}: no note contains "${s}"`); // notes
    for (const s of k.steps ?? []) if (!steps.some((t) => t.includes(s))) failures.push(`${v.id}: no step contains "${s}"`); // steps
    if (v.noWarning && (rec.warnings ?? []).some((w) => w.includes(v.noWarning as string))) failures.push(`${v.id}: a warning contains "${v.noWarning}"`); // must not fire
  } // vectors
  // The page's Examples and chips must be computed vectors (D-83: the Example is verbatim from a golden vector).
  const topo = (v: StpVector): string | undefined => (v.request && v.request.mode === "election" ? v.request.topology : undefined); // a vector's topology
  if (!STP_VECTORS.some((v) => v.election && topo(v) === EXAMPLE_ELECTION_REQUEST.topology)) failures.push("examples: the election Example is not a computed vector"); // the Example
  for (const s of SAMPLES) if (!STP_VECTORS.some((v) => v.election && topo(v) === s.topology && v.request?.mode === "election" && v.request.method === s.method)) failures.push(`examples: chip ${s.id} is not a computed vector`); // the chips
  if (!STP_VECTORS.some((v) => v.cost && v.request?.mode === "cost" && v.request.speed === EXAMPLE_COST_REQUEST.speed)) failures.push("examples: the cost Example is not a computed vector"); // the cost Example
  if (COST_TABLE.length !== SPEEDS.length) failures.push(`costs: ${COST_TABLE.length} documented rows from the sources, ${SPEEDS.length} in the engine`); // the table matches the documents
  return { setId: GOLDEN_VECTOR_SET_ID, total: STP_VECTORS.length, passed: STP_VECTORS.length - new Set(failures.map((f) => f.split(":")[0])).size, failures }; // the report
} // verifyVectors
